// Generated by prepare_submissions.py from submissions.json. Edit the template, then regenerate.
// Trace chunk @@CHUNK@@: derive(item -> source paragraph or slice obligation), verify(item -> verification
// Constraint) and satisfy(model element -> item). Anchors are frozen layer|class|name keys; a missing or
// ambiguous anchor is rejected. Run once, after every import chunk.
assert session.sessionResource.URI.toString().toLowerCase().contains('/fsae-2027-electric-arcadia/'): 'Only the disposable acceptance project is permitted'
assert api.layer('SA').system.summary == 'FSAE2027:bootstrap-v1': 'Missing the acceptance project marker'
def req = api.requirements()
assert req.available() && req.viewpointEnabled()

// Identifier map built once from the source, slice and submission modules.
def modules = req.listModules().collectEntries { [(it.ReqIFIdentifier): it] }
def module = modules[@@MODULE_ID@@]
assert module != null: 'Run 30-create-submissions first'
assert req.requirements(module).size() == @@ITEM_COUNT@@: 'Run every 31-import chunk before tracing'
def byId = [:]
['FSAE-2027-V1:source-module', 'FSAE2027:SD:derived-module', 'FSAE2027:DD:module', 'FSAE2027:VP:derived-module', @@MODULE_ID@@].each { id ->
    assert modules[id] != null: 'Missing module ' + id
    req.requirements(modules[id]).each { byId[it.ReqIFIdentifier] = it }
}
def items = @@ITEMS@@

// One name/class scan per layer for the anchors this chunk needs.
def wanted = items.collectMany { it.verify + it.satisfy } as Set
def elements = [:]
['OA', 'SA', 'LA', 'PA', 'EPBS'].each { layer ->
    def iterator = api.layer(layer).eAllContents()
    while (iterator.hasNext()) {
        def element = iterator.next()
        def nameFeature = element.eClass().getEStructuralFeature('name')
        if (nameFeature == null) continue
        def key = layer + '|' + element.eClass().name + '|' + element.eGet(nameFeature)
        if (wanted.contains(key)) {
            assert !elements.containsKey(key): 'Ambiguous model anchor ' + key
            elements[key] = element
        }
    }
}
wanted.each { assert elements.containsKey(it): 'Missing model anchor ' + it }
def target = { id -> byId[id.startsWith('FSAE2027:') ? id : 'FSAE-2027-V1:' + id] }
items.each { item ->
    def requirement = byId[item.id]
    assert requirement != null: 'Missing item ' + item.id
    assert requirement.ownedRelations.isEmpty(): 'Item already traced, review it instead of replaying: ' + item.id
    item.derive.each { assert target(it) != null: 'Missing derive target ' + it }
}
def counts = [derive: 0, verify: 0, satisfy: 0]
api.batch('Trace submission items ' + @@CHUNK@@) {
    items.each { item ->
        def requirement = byId[item.id]
        item.derive.each { req.derive(requirement, target(it)); counts.derive++ }
        item.verify.each { req.verify(requirement, elements[it]); counts.verify++ }
        item.satisfy.each { req.satisfy(elements[it], requirement); counts.satisfy++ }
    }
}
log.info('Submission trace chunk ' + @@CHUNK@@ + ' applied: ' + counts)
return [chunk: @@CHUNK@@, items: items.size(), links: counts]
